"""Independent analysis checks and readable report; no model/new predictions."""
from pathlib import Path
import json,hashlib
import numpy as np
R=Path(__file__).resolve().parents[3];O=Path(__file__).resolve().parent
def rd(p):return json.loads(Path(p).read_text())
def dump(p,x):Path(p).write_text(json.dumps(x,indent=2,allow_nan=False)+'\n')
def tab(h,rows):return '\n'.join(['| '+' | '.join(h)+' |','|'+'|'.join(['---']*len(h))+'|']+['| '+' | '.join(map(str,r))+' |' for r in rows])
def main():
 reg=rd(R/'research/round134/INPUT_REGISTRY_PRIVATE.json');rows=rd(O/'ALL_ROWS_PRIVATE.json');summary=rd(O/'SUMMARY.json');metrics=summary['metrics']['design_weighted'];n=0
 for e,r in zip(reg,rows):
  name=e['source']+'_to_'+e['target'];sid=e['row']['id'];assert name==r['direction'] and sid==r['id_PRIVATE'];a=np.load(R/'crossplatform/round97'/name/'samples_PRIVATE'/(sid+'.npz'));z=np.load(R/'crossplatform/round131/formal'/name/'prefix_PRIVATE'/(sid+'.npz'));old=rd(R/'crossplatform/round97'/name/'records_PRIVATE'/(sid+'.json'))['input_receipt'];new=rd(R/'crossplatform/round131/formal'/name/'records_PRIVATE'/(sid+'.json'))['source_prefix'];assert int(a['anno_index'])==e['row']['anno_index'];assert np.array_equal(a['point_indices'],z['point_indices']) and np.array_equal(a['source_boxes'],z['boxes'])
  for key in ['actual_model_text_sha256','phrase_sha256','point_sample_sha256','point_indices_sha256','source_checkpoint_sha256','source_platform']:assert old[key]==new[key],(name,key)
  assert old['phrase_sha256']==hashlib.sha256(e['row']['caption'].encode()).hexdigest()
  assert abs((1-r['R134'])-(r['geometry_gap']+r['selection_gap']))<1e-12
  assert abs(r['selection_gap']-r['between_geometric_group_gap']-r['within_geometric_group_gap'])<1e-12
  n+=1
 for key in ['class25','class50']:
  parts=[p for p in summary['threshold_partition'] if p['threshold']==key];assert sum(p['n'] for p in parts)==1798;assert abs(sum(p['design_weighted_mass_percent'] for p in parts)-100)<1e-10
 # Independently sum per-direction weighted arithmetic from stored row scores.
 for k in ['original_source','prepared_frozen_A','foundation_A','frozen_FAB','R134','A256_oracle']:
  expected=0.
  for name in sorted({r['direction'] for r in rows}):
   rr=[r for r in rows if r['direction']==name];expected+=sum(r['weight']*r[k] for r in rr)/sum(r['weight'] for r in rr)*100/6
  assert abs(expected-metrics[k]['mIoU'])<1e-10
 groups=[]
 for available in [False,True]:
  rr=[r for r in rows if r['B_available']==available];groups.append({'B_available':available,'n':len(rr),'design_weighted_mass_percent':sum(r['macro_weight'] for r in rr)*100,'prepared_to_foundation_A_contribution_pp':sum((r['foundation_A']-r['prepared_frozen_A'])*r['macro_weight'] for r in rr)*100,'foundation_A_to_FAB_contribution_pp':sum((r['frozen_FAB']-r['foundation_A'])*r['macro_weight'] for r in rr)*100,'FAB_to_R134_contribution_pp':sum((r['R134']-r['frozen_FAB'])*r['macro_weight'] for r in rr)*100,'R134_minus_full_prepared_contribution_pp':sum((r['R134']-r['prepared_frozen_A'])*r['macro_weight'] for r in rr)*100})
 dump(O/'SUBGROUP_STAGE_ACCOUNTING.json',groups)
 audit={'status':'PASS_ALL1798_CAPTION_SAMPLE_CHECKPOINT_ANNOTATION_INDEX_BOX_BRIDGES_AND_ORACLE_ARITHMETIC','n':n,'new_model_or_training_runs':0,'new_predictions':0,'raw_GT_or_media_reads':0,'geometric_IoU_computations':0,'method_changes':False,'FINAL_access':False};dump(O/'AUDIT.json',audit)
 m=metrics;g=summary['gap_decomposition'];part=[p for p in summary['threshold_partition'] if p['threshold']=='class25'];loss=summary['TTA_gain_loss'];cov=summary['supervision_coverage'];rank=summary['ranking'];p134=rd(R/'research/round134/SIGNAL_SUMMARY.json')
 text=['# R134 pipeline-versus-GT analysis — cached evidence only','','No optimization launched and no method changed. R135 does not exist; no GPU research process was running. This analysis only regroups sealed predictions and already-computed R131 A256 IoU vectors. No raw media/annotation reads, new geometric scoring, model forward, training or FINAL access. All1798 historically exposed rows remain; primary metric uses equal six directions and original within-direction design weights. Raw counts do not equal design-weighted rates.','','## Main finding','','The current TTA path improves over its own native-foundation zero state, but is below the intact source-prepared R91 frozen-A model. The previous +0.2435pp statement was conditional on that weaker starting path, not an advantage over the strongest existing frozen system. Source-prepared frozen A13.394463 vsR13412.873988: -0.520475pp. Raw macro also negative(13.403041 vs12.911249). Same descriptions, point indices, source checkpoints, annotation indices and A256 boxes are independently matched.','','## Actual frozen/initialization/fusion/update stages','',tab(['State','mIoU%','Acc25%','Acc50%'],[[k]+[f'{m[k][s]:.6f}' for s in ['mIoU','Acc25','Acc50']] for k in ['original_source','prepared_frozen_A','foundation_A','foundation_B','frozen_FAB','LOG3','R134','A256_oracle']]),'',
 'The intact prepared-A scorer uses trained point/RGB fusion and live R91 competition interface. start123 zeros point_adapter.up.weight/bias and gate_P before fitting. body127 disables the live route/interface, then uses current query/text representations plus fixed source-A late_RGB and residual. Thus prepared-A→foundation-A changes initialization and readout together; -0.683653pp is a bundled observed loss, not proof that one zeroed tensor alone caused it. Foundation-A→registered-FAB is a matched-input fusion change at the same reader and gives -0.080292pp overall. TTA recovers +0.243470pp, leaving the complete system -0.520475pp below intact prepared-A. These are stage-accounting comparisons, not a completed causal ablation of each reset/readout operation.','', 'Subgroup contributions use the original full-cohort denominator, not renormalized subset means:','', '```json',json.dumps(groups,indent=2),'```','',
 '## Fixed-box geometric ceiling and selection loss','','The exact cached-IoU identity is 1-IoU(final) = [1-maxIoU(A256)] + [maxIoU(A256)-IoU(final)]. In aggregate, geometric candidate-quality ceiling gap65.199320pp and selection gap21.926692pp sum to total87.126012pp. This is an oracle accounting identity, not causal proof that box regression alone repairs the first term.','',tab(['GT-only diagnostic','mIoU%','Acc25%','Acc50%'],[[k]+[f'{m[k][s]:.6f}' for s in ['mIoU','Acc25','Acc50']] for k in ['A256_oracle','R134','selected_group_oracle','S_oracle','C_oracle']]),'',
 'A256 has an Acc25-good box for1437 inputs, but the final decision passes442;995 final Acc25 failures therefore have an available passing box. At Acc50,1518 inputs have no passing A256 box. Selecting among fixed boxes can address the former ranking gap but cannot make the latter1518 cross that threshold. Geometric duplicate grouping is only a proxy: within-selected-group oracle gains0.102314pp, while between-geometric-group regret21.824378pp. This does not certify true object identity.','','## Where final Acc25 failures lose supervision','',tab(['Category','Raw count','Weighted cohort mass%','Selection-regret contribution pp'],[[p['category'],p['n'],f"{p['design_weighted_mass_percent']:.4f}",f"{p['selection_regret_contribution_pp']:.4f}"] for p in part]),'',
 'S/C are supervision qualification/retention sets, not hard filters of the final A256 output. Consequently S/C global oracles can be lower than actual model mIoU; do not add A256→S→C differences as if every final selection were restricted to C. Empty support has oracle0 only for measuring supervision reach. Among996 zero-step Acc25 errors with a passing A256 box:428 have usableB,355 have a good box inS,259 inC,7 have a retained recoverable candidate with the R134 explicit order against the old top. This shows an observation/supervision reach problem in addition to internal ordering.','','## TTA beneficial changes versus damage','',tab(['Baseline','Better','Worse','Same','Positive pp','Negative pp','Net pp','GT-only no-harm upper mIoU'],[[p['baseline'],p['better'],p['worse'],p['same'],f"{p['positive_contribution_pp']:+.6f}",f"{p['negative_contribution_pp']:+.6f}",f"{p['net_pp']:+.6f}",f"{p['GT_only_no_harm_selection_upper_bound']:.6f}"] for p in loss]),'',
 'Against same-information frozen-FAB, R134 has54 improvements31 harms: +0.447537pp beneficial contribution and -0.204067pp damage. Even an unavailable GT selector that removed every one of those harms reaches only13.078055%, below intact prepared-A13.394463%. Reducing adaptation damage alone therefore cannot close the current whole-system gap. This oracle is descriptive only and is never a deployment selector.','','## Signal qualification and text readout boundaries','','R134 freezes7157 pair constraints, but their fixed initial-FAB representative-box IoU directions are1097better/819worse/5241tied. The non-tied better fraction is57.25%; this is a box-quality proxy, not verified instance-label precision. Only12 inputs have a pair explicitly opposing initial top, and7 are zero-error/recoverable/retained. Sparse decisive signal explains why decreasing ordinal loss does not imply broad grounding correction.','','Final native matching still uses firstnoun_mask from model51, with all-content fallback; complete text enters the encoders. Therefore attributes/references may affect contextual embeddings but are not guaranteed separately aligned by the final positive-token readout. This is an implementation observation, not GT proof that text-span failure causes the dominant loss in this cohort. No new span oracle or text intervention was run.','','## Analysis conclusion and next decision boundary','','First restore/compare against intact source-prepared frozen behavior and isolate reset/readout/fusion losses before optimizing R134 step/loss weights. For fixed A256, target selection remains a large available Acc25 opportunity; for Acc50, candidate quality is a hard ceiling. Missing usableB and missing supported/retained good candidates limit where current TTA can act. Teacher ordering quality and shared-update damage are subsequent limits, not the whole gap. Do not use the508 unchanged-update subset as the denominator for all pipeline failures. This turn remains analysis-only: no R135, no new TTA/fusion/teacher change and no future run queued.','','## Verification','','```json',json.dumps(audit,indent=2),'```','']
 (O/'REPORT.md').write_text('\n'.join(text));print(json.dumps({'audit':audit,'stage_subgroups':groups},indent=2))
if __name__=='__main__':main()
